package dev.abros.rivet.client;
import com.google.gson.*;
import dev.abros.rivet.core.*;
import net.minecraft.client.gui.GuiGraphics;
import net.minecraft.client.gui.components.Button;
import net.minecraft.client.gui.screens.Screen;
import net.minecraft.network.chat.Component;
import java.util.*;
/** LuckPerms role permissions; editing requires a separate server-verified capability. */
final class RolePreviewScreen extends ScrollScreen implements CommunityScreen.Receiver {
 private final Screen parent;private final RequestSession session=new RequestSession();private JsonArray roles=new JsonArray();private boolean loaded,busy,editable;private long refreshAt;private int selected;private String notice="";
 RolePreviewScreen(Screen parent){super(Client.tr("ui.role_permissions_preview_e35dff84"));this.parent=parent;}
 private int w(){return Math.min(430,width-32);}private int x(){return (width-w())/2;}private int top(){return UiDialog.top(height,350);}private int end(){return height-top();}
 private void load(){var j=new JsonObject();j.addProperty("action","rolePreview");busy=true;refreshAt=System.currentTimeMillis()+5000;ServerMenuClient.request(session.begin(j,false,System.currentTimeMillis()));}
 @Override protected void init(){if(!roles.isEmpty()){selected=Math.min(selected,roles.size()-1);var role=roles.get(selected).getAsJsonObject();addRenderableWidget(UiActions.button(Component.literal(Json.str(role,"name")+" ▾"),UiActions.Tone.NORMAL,"",b->minecraft.setScreen(new ChoicePopup(this,Client.text("ui.select_a_role_abb10714"),roles.asList().stream().map(e->Json.str(e.getAsJsonObject(),"name")).toList(),n->{selected=n;resetScroll();rebuildWidgets();},b).current(selected))).bounds(x()+12,top()+36,UiSearchToolbar.contentWidth(w()-24),20).build());var caps=role.getAsJsonObject("capabilities");var keys=PermissionCatalog.ENTRIES;scrollArea(keys.size(),new dev.abros.rivet.core.NativeLayout.Box(x()+12,top()+70,Math.max(0,w()-24),Math.max(0,(end()-96)-(top()+70))),26);for(int n=firstRow;n<Math.min(keys.size(),firstRow+visibleRows);n++){var entry=keys.get(n);String key=entry.node();String assignment=role.has("direct")?Json.opt(role.getAsJsonObject("direct"),key,"inherit"):"inherit";boolean effective=caps.has(key)&&caps.get(key).getAsBoolean();var button=addRenderableWidget(UiActions.button(Component.literal(label(key)+" · "+Client.text("permissions."+assignment)),UiActions.Tone.NORMAL,"",b->edit(Json.str(role,"name"),key,assignment)).bounds(x()+12,top()+70+(n-firstRow)*26,w()-24,22).build());button.active=editable&&!busy;button.setTooltip(net.minecraft.client.gui.components.Tooltip.create(Component.literal(Client.text(entry.key()+".description")+"\n"+key+"\n"+Client.text(entry.adminDefault()?"permissions.included":"permissions.separate")+"\n"+Client.text("permissions.effective")+Client.text(effective?"permissions.yes":"permissions.no"))));}}
  addRenderableWidget(UiActions.button(Client.tr("permissions.refresh"),UiActions.Tone.NORMAL,"",b->load()).bounds(x()+12,end()-92,w()-24,20).build()).active=!busy;
  UiActions.close(new dev.abros.rivet.core.NativeLayout.Box(x(),end()-28,w()-12,20),this::addRenderableWidget,this::onClose);if(!loaded){loaded=true;load();}}
 private static String label(String key){return Client.text(PermissionCatalog.require(key).key());}
 private void edit(String role,String permission,String expected){if(!editable||busy)return;var values=List.of("inherit","true","false");minecraft.setScreen(new ChoicePopup(this,label(permission),values.stream().map(v->Client.text("permissions."+v)).toList(),n->{String value=values.get(n);if(value.equals(expected))return;minecraft.setScreen(new UiConfirmDialog(yes->{minecraft.setScreen(this);if(yes){var q=new JsonObject();q.addProperty("action","rolePermission");q.addProperty("role",role);q.addProperty("permission",permission);q.addProperty("value",value);q.addProperty("expected",expected);busy=true;ServerMenuClient.request(session.begin(q,true,System.currentTimeMillis()));rebuildWidgets();}},Client.tr("permissions.confirm"),Component.literal(role+" · "+label(permission)+"\n"+Client.text("permissions."+expected)+" → "+Client.text("permissions."+value))));}).current(values.indexOf(expected)));}
 public void receiveCommunity(JsonObject j){if(!session.receive(j))return;busy=false;if(j.has("saved")){load();rebuildWidgets();return;}if(j.has("error"))notice=Json.opt(j,"text",Client.text("ui.unavailable_949ac1f2"));else if(j.has("roles")){String selection=roles.isEmpty()?"":Json.str(roles.get(Math.min(selected,roles.size()-1)).getAsJsonObject(),"name");roles=j.getAsJsonArray("roles");for(int n=0;n<roles.size();n++)if(Json.str(roles.get(n).getAsJsonObject(),"name").equals(selection)){selected=n;break;}editable=j.has("editable")&&j.get("editable").getAsBoolean();notice=roles.isEmpty()?Client.text("ui.could_not_retrieve_loaded_luckperms_roles_d64401c8"):Client.text(!Json.opt(j,"provider","luckperms").equals("luckperms")?"permissions.noProvider":editable?"permissions.scope":"permissions.readOnly");}rebuildWidgets();}
 @Override public void tick(){if(loaded&&!busy&&System.currentTimeMillis()>=refreshAt)load();if(session.timeout(System.currentTimeMillis())){busy=false;notice=Client.text("ui.no_response_reopen_this_window_a3ea9202");rebuildWidgets();}if(!ServerMenuClient.admin())onClose();}
 @Override public void renderBackground(GuiGraphics g,int mx,int my,float d){UiDialog.draw(g,width,w(),top(),end());}
 @Override public void render(GuiGraphics g,int mx,int my,float d){UiDialog.render(parent,this,g,d,()->{super.render(g,mx,my,d);UiHeading.dialog(g,font,title,x()+12,top(),w()-24);Ui.status(g,font,busy&&roles.isEmpty()?Client.text("ui.loading_roles_4386b264"):notice,x()+12,end()-66,w()-24,end()-34);});}
 @Override public void onClose(){session.cancel();minecraft.setScreen(parent);}
 @Override public boolean isPauseScreen(){return false;}
}
